// Ported from the Node app's Sequelize model HostelRoom (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class HostelRoomConfiguration : IEntityTypeConfiguration<HostelRoom>
{
    public void Configure(EntityTypeBuilder<HostelRoom> builder)
    {
        builder.ToTable("hostel_rooms");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.HostelId).HasColumnName("hostel_id");
        builder.Property(e => e.RoomNo).HasColumnName("room_no").HasColumnType("nvarchar(20)").HasMaxLength(20).IsRequired();
        builder.Property(e => e.Capacity).HasColumnName("capacity");
        builder.Property(e => e.MonthlyFee).HasColumnName("monthly_fee").HasColumnType("decimal(10,2)").HasDefaultValueSql("0");
        builder.HasIndex(e => new { e.HostelId, e.RoomNo }).IsUnique().HasDatabaseName("uq_hostel_room");
        builder.HasOne(e => e.Hostel).WithMany(p => p.HostelRooms).HasForeignKey(e => e.HostelId).OnDelete(DeleteBehavior.NoAction);
    }
}
